// shell (v5.5): LAN room discovery -- the owner's listening port is random (PORT / :0), so another
// phone on the same Wi-Fi cannot find it by sweeping ports. Discovery is therefore pinned to one
// well-known port (LAN_DISCOVERY_PORT below) and the real port is handed back in /lan/rooms.port.
// Every route is gated on the socket peer being loopback/private (net.js isLocalIp): X-Forwarded-For
// / CF-Connecting-IP are never consulted, so a public request cannot masquerade as a LAN peer. A
// public peer and an unknown room code get the SAME 404 body -- the response never reveals whether a
// code exists (LAN-discoverable, not internet-enumerable).
const LAN_DISCOVERY_PORT = 32123;
// 公开集合：房主在房间页显式「公开到局域网」才进这里。默认空 —— 无条件列出房号等于让同一 Wi-Fi 上
// 的任何设备无需邀请即可进房（审查发现#1）。
const lanPublic = new Set();
const lanRoomView = (r) => ({
  code: r.code,
  name: (r.seats.find((s) => s && !s.isBot && !s.left) || {}).name || r.code,
  mode: r.mode,
  difficulty: r.difficulty,
  seats: r.seats.length,
  humans: r.activeHumans().length,
  inMatch: r.match != null,
});
// 只列房主显式公开过的房间；房间消失就顺手清掉标记（集合自愈，不需要额外定时器）。
const lanRooms = () => {
  const out = [];
  for (const code of Array.from(lanPublic)) {
    const r = lobby.getRoom(code);
    if (!r || r.mode !== 'coop') { lanPublic.delete(code); continue; }
    out.push(lanRoomView(r));
  }
  return out;
};
const isLanPeer = (req) => isLocalIp(normalizeIp(req && req.socket && req.socket.remoteAddress));
/** 回环来源 = 房主自己的页面（本机 WebView 走 127.0.0.1）。公开开关只允许它拨动。 */
const isLoopbackPeer = (req) => {
  const ip = normalizeIp(req && req.socket && req.socket.remoteAddress);
  return ip === '127.0.0.1' || ip === '::1';
};
const lanNotFound = (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  sendJson(req, res, 404, { ok: false, error: 'not found' });
};
/** 最小 JSON 体读取：本文件其余路由都是 GET，故自带 4KB 上限 + 3s 超时，超限即断开。 */
const readJsonBody = (req, cb) => {
  let body = '';
  let done = false;
  const finish = (v) => { if (done) return; done = true; cb(v); };
  const bail = () => { finish(null); try { req.destroy(); } catch { /* ignore */ } };
  req.setTimeout(3000, bail);
  req.on('data', (c) => { body += c; if (body.length > 4096) bail(); });
  req.on('end', () => { try { finish(JSON.parse(body || '{}')); } catch { finish(null); } });
  req.on('error', () => finish(null));
};
/** Serve the LAN routes -- true when the request was handled. */
const handleLanRoute = (req, res, parts) => {
  if (parts.rawPath === '/lan/publish') {
    res.setHeader('Access-Control-Allow-Origin', '*');
    // 只接受回环 POST：同网段邻居既不能替别人把房间公开出去，也不能取消别人的公开。
    if (req.method !== 'POST' || !isLoopbackPeer(req)) { lanNotFound(req, res); return true; }
    readJsonBody(req, (body) => {
      const code = String((body && body.code) || '').toUpperCase();
      if (!/^[A-Z0-9]{4}$/.test(code) || !lobby.getRoom(code)) { lanNotFound(req, res); return; }
      if (body && body.on) lanPublic.add(code); else lanPublic.delete(code);
      sendJson(req, res, 200, { ok: true, code, on: lanPublic.has(code) });
    });
    return true;
  }
  if (parts.rawPath !== '/lan/rooms' && parts.rawPath !== '/lan/room') return false;
  res.setHeader('Access-Control-Allow-Origin', '*');
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    sendJson(req, res, 405, { ok: false, error: 'method not allowed' });
    return true;
  }
  if (!isLanPeer(req)) { lanNotFound(req, res); return true; }
  if (parts.rawPath === '/lan/rooms') {
    sendJson(req, res, 200, { ok: true, app: APP_VERSION, protocol: PROTOCOL_VERSION, port: actualPort, rooms: lanRooms() });
    return true;
  }
  const code = String(new URLSearchParams(parts.query).get('code') || '').toUpperCase();
  if (!/^[A-Z0-9]{4}$/.test(code)) { lanNotFound(req, res); return true; }
  const room = lobby.getRoom(code);
  if (!room) { lanNotFound(req, res); return true; }
  sendJson(req, res, 200, { ok: true, port: actualPort, ...lanRoomView(room) });
  return true;
};

const server = http.createServer((req, res) => {

if (!parts) { sendError(req, res, 400, '请求地址无效 · Bad request'); return; }
// shell (v5.5): LAN routes must run BEFORE the global GET/HEAD gate below -- /lan/publish is a
// POST (the host's own page toggles LAN publication) and the gate would 405 it away. Anchored on
// the !parts line above: the LAN handler itself contains an identical method check, so anchoring
// on that alone would splice this call into handleLanRoute and recurse forever.
if (handleLanRoute(req, res, parts)) return;
if (req.method !== 'GET' && req.method !== 'HEAD') {

const url = `http://${host === '0.0.0.0' || host === '::' ? 'localhost' : host}:${actualPort}`;

// shell (v5.5): fixed-port LAN discovery listener. The owner's real port is random, so a scanner
// cannot enumerate it -- pin discovery to LAN_DISCOVERY_PORT and serve ONLY the two read-only LAN
// routes there (no static files, no /healthz, no WS, and deliberately NOT /lan/publish: the
// discovery surface must not be able to change state). EADDRINUSE is swallowed (another instance on
// this phone already holds the port): the owner's server MUST still start. unref() keeps it from
// holding the process open.
const discoveryServer = http.createServer((req, res) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  const parts = splitUrl(req.url || '/');
  if (parts && (parts.rawPath === '/lan/rooms' || parts.rawPath === '/lan/room')
      && handleLanRoute(req, res, parts)) return;
  lanNotFound(req, res);
});
discoveryServer.on('error', (e) => {
  if (e && e.code === 'EADDRINUSE') log.warn?.(`[lan] discovery port ${LAN_DISCOVERY_PORT} busy -- LAN discovery disabled (server unaffected)`);
  else log.warn?.('[lan] discovery server error', e);
});
discoveryServer.listen(LAN_DISCOVERY_PORT, host);
discoveryServer.unref();
